.jui-terms {
  align-items: center;
  display: flex;
  flex-direction: column;
  max-width: 340px;
  width: 100%;
}
.jui-terms-next:focus-visible {
  outline: 2px solid rgb(47 123 212 / 0.28);
  outline-offset: 3px;
}
.jui-terms-row {
  align-items: center;
  color: light-dark(rgba(0, 0, 0, 0.58), #aeb5bd);
  cursor: pointer;
  display: flex;
  font-size: 16px;
  font-weight: 400;
  gap: 10px;
  line-height: 1.2;
  margin-top: 20px;
  position: relative;
}
.jui-terms-row input {
  height: 1px;
  opacity: 0;
  position: absolute;
  width: 1px;
}
.jui-terms-row b {
  color: light-dark(#181818, #f3f5f6);
  font-weight: 520;
  text-decoration: underline dotted
    light-dark(rgba(0, 0, 0, 0.2), rgba(255, 255, 255, 0.3)) 1px;
  text-underline-offset: 6px;
}
.jui-terms-box {
  align-items: center;
  background: light-dark(#fff, #202428);
  border: 1px solid light-dark(rgba(0, 0, 0, 0.06), rgba(255, 255, 255, 0.16));
  border-radius: 10px;
  box-shadow:
    inset 0 1px 1px rgba(0, 0, 0, 0.025),
    0 1px 2px rgba(20, 24, 40, 0.025);
  color: light-dark(#111, #f3f5f6);
  display: flex;
  flex: 0 0 auto;
  height: 28px;
  justify-content: center;
  transition:
    border-color 0.18s cubic-bezier(0.2, 0.7, 0.2, 1),
    box-shadow 0.18s cubic-bezier(0.2, 0.7, 0.2, 1),
    background 0.18s cubic-bezier(0.2, 0.7, 0.2, 1);
  width: 28px;
}
.jui-terms-box svg {
  fill: none;
  height: 14px;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2;
  width: 14px;
}
.jui-terms-row:hover .jui-terms-box {
  border-color: light-dark(rgba(0, 0, 0, 0.11), rgba(255, 255, 255, 0.25));
  box-shadow:
    inset 0 1px 1px rgba(0, 0, 0, 0.025),
    0 3px 9px rgba(20, 24, 40, 0.06);
}
.jui-terms-row:has(input:checked) .jui-terms-box {
  background: light-dark(#111, #f3f5f6);
  border-color: light-dark(#111, #f3f5f6);
  color: light-dark(#fff, #202428);
}
.jui-terms-row[data-nudging] .jui-terms-box {
  border-color: light-dark(rgba(0, 0, 0, 0.16), rgba(255, 255, 255, 0.3));
  box-shadow:
    0 0 0 4px rgba(0, 0, 0, 0.025),
    0 5px 16px rgba(20, 24, 40, 0.09);
}
.jui-terms-error {
  align-items: center;
  color: light-dark(#e73c4e, #ff7c8c);
  display: flex;
  font-size: 16px;
  font-weight: 400;
  justify-content: center;
  line-height: 1.32;
  min-height: 48px;
  padding-top: 16px;
  text-align: center;
  width: min(100%, 330px);
}
.jui-terms-next {
  appearance: none;
  background: light-dark(#111, #f3f5f6);
  border: 0;
  border-radius: 999px;
  box-shadow: 0 8px 20px rgba(20, 24, 40, 0.11);
  color: light-dark(#fff, #202428);
  cursor: pointer;
  font: inherit;
  font-size: 15px;
  font-weight: 560;
  height: 40px;
  margin-top: 0;
  min-width: 112px;
  padding: 0 22px;
  transition:
    background 0.18s cubic-bezier(0.2, 0.7, 0.2, 1),
    transform 0.18s cubic-bezier(0.2, 0.7, 0.2, 1),
    box-shadow 0.18s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.jui-terms-next:hover {
  background: light-dark(#242424, #dce1e6);
  box-shadow: 0 10px 24px rgba(20, 24, 40, 0.14);
  transform: translateY(-1px);
}
.jui-terms-next:active {
  transform: translateY(0) scale(0.98);
}

.jui-terms {
  color: light-dark(#171717, #f3f5f6);
}
.jui-terms,
.jui-terms * {
  box-sizing: border-box;
}
.jui-terms-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
.jui-terms-next:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.jui-terms-row:has(input:disabled) {
  opacity: 0.5;
  cursor: not-allowed;
}
.jui-terms-row:has(input:focus-visible) .jui-terms-box {
  outline: 2px solid rgb(47 123 212 / 0.5);
  outline-offset: 3px;
}
@media (max-width: 520px) {
  .jui-terms-row {
    align-items: center;
    font-size: 15px;
    gap: 10px;
    margin-top: 20px;
  }
  .jui-terms-error {
    font-size: 15px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .jui-terms-next:hover,
  .jui-terms-next:active {
    transform: none;
  }
  .jui-terms-next,
  .jui-terms-box {
    transition: none;
  }
}

"use client";
import {
  useEffect,
  useId,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { cn } from "@/lib/utils";
import "./terms-nudge.css";
export type TermsNudgeProps = Omit<ComponentProps<"div">, "onChange"> & {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  onContinue?: () => void;
  label?: ReactNode;
  buttonLabel?: string;
  errorMessage?: string;
  feedback?: "nudge" | "message";
  disabled?: boolean;
};
export function TermsNudge({
  checked,
  defaultChecked = false,
  onCheckedChange,
  onContinue,
  label = (
    <>
      I accept the <b>Terms &amp; Conditions</b>
    </>
  ),
  buttonLabel = "下一步",
  errorMessage = "You must accept the Terms & Conditions to continue.",
  feedback = "nudge",
  disabled,
  className,
  ...props
}: TermsNudgeProps) {
  const [internal, setInternal] = useState(defaultChecked);
  const [attempted, setAttempted] = useState(false);
  const row = useRef<HTMLLabelElement>(null);
  const animation = useRef<Animation | null>(null);
  const id = useId();
  const accepted = checked ?? internal;
  const invalid = attempted && !accepted;
  useEffect(() => () => animation.current?.cancel(), []);
  function proceed() {
    if (accepted) {
      setAttempted(false);
      onContinue?.();
      return;
    }
    setAttempted(true);
    animation.current?.cancel();
    if (
      feedback === "nudge" &&
      !matchMedia("(prefers-reduced-motion: reduce)").matches
    ) {
      animation.current =
        row.current?.animate(
          [
            { transform: "translateX(0)", offset: 0 },
            { transform: "translateX(-9px)", offset: 0.18 },
            { transform: "translateX(8px)", offset: 0.36 },
            { transform: "translateX(-5px)", offset: 0.54 },
            { transform: "translateX(3px)", offset: 0.72 },
            { transform: "translateX(0)", offset: 1 },
          ].map((frame) => ({
            ...frame,
            easing: "cubic-bezier(.16, 1, .3, 1)",
          })),
          { duration: 420 },
        ) ?? null;
    }
  }
  return (
    <div
      {...props}
      data-slot="terms-nudge"
      className={cn("jui-terms", className)}
    >
      <button
        type="button"
        className="jui-terms-next"
        disabled={disabled}
        onClick={proceed}
      >
        {buttonLabel}
      </button>
      <label
        ref={row}
        className="jui-terms-row"
        data-nudging={(feedback === "nudge" && invalid) || undefined}
      >
        <span className="jui-terms-box" aria-hidden="true">
          {accepted && (
            <svg viewBox="0 0 18 18">
              <path d="m4.2 9.2 3.1 3.1 6.5-7" />
            </svg>
          )}
        </span>
        <input
          type="checkbox"
          checked={accepted}
          disabled={disabled}
          aria-invalid={invalid}
          aria-describedby={invalid ? id : undefined}
          onChange={(e) => {
            if (checked === undefined) setInternal(e.target.checked);
            onCheckedChange?.(e.target.checked);
            setAttempted(false);
            animation.current?.cancel();
          }}
        />
        <span>{label}</span>
      </label>
      <div className="jui-terms-error">
        <span
          id={id}
          aria-live="polite"
          className={feedback === "nudge" ? "jui-terms-sr" : undefined}
        >
          {invalid ? errorMessage : ""}
        </span>
      </div>
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
